{"code":"def transform(g):
    # enlarge by repeating a decorated tile; decoration marks the zero cells
    # lying on the complementary diagonal bands between matching markers.
    h,w=len(g),len(g[0])
    t=[r[:] for r in g]
    pts=[(i,j) for i in range(h) for j in range(w) if g[i][j]!=0]
    if len(pts)==2:
        (a,b),(c,d)=pts
        for i in range(h):
            for j in range(w):
                if t[i][j]==0:
                    # mark cells on either of the two diagonal projections
                    if (i-a)*(d-b)==(j-b)*(c-a) or (i-a)*(d-b)==-(j-b)*(c-a): t[i][j]=8
    return [t[i%h]+t[i%h] for i in range(2*h)]"}

